 public const string Folder="Assets/_Project/WorldBuilder/Island023", Art="Assets/_Project/Art/Island023";
 [Serializable] public class Plot {public string id,model;public Vector3 position;public float yaw;public Plot(string i,string m,float x,float z,float y,float a=0){id=i;model=m;position=new Vector3(x,y,z);yaw=a;}}
 public static Plot[] Plots={
 new Plot("B1","House",-31,-28,3.5f,-15),new Plot("B2","TallHouse",-30,-10,6,15),new Plot("B3","House",-40,7,9,20),new Plot("B4","TallHouse",-24,15,11,15),
 new Plot("A1","House",-17,31,14,10),new Plot("A2","TallHouse",31,22,11,-20),new Plot("A3","House",20,10,8,-10),new Plot("A4","House",48,5,7,-40),
 new Plot("L1","TallHouse",40,-24,3.5f,-20),new Plot("L2","House",-7,-31,2.8f,10),new Plot("L3","House",48,34,14,15),new Plot("L4 — casa isolada","OldHouse",-52,43,18,5),
 new Plot("Venda","Shop",-10,3,7,5),new Plot("Oficina","Shop",0,6,7,5),new Plot("Salão comunitário","Hall",18,-4,6,-20),new Plot("Igreja","Church",-2,38,15,0),new Plot("Armazém do cais","Warehouse",-36,-43,2,0)};
 public class Route {public string id;public float width;public List<Vector3> points=new List<Vector3>();public Route(string i,float w,params Vector3[] p){id=i;width=w;for(int j=0;j<p.Length-1;j++){var a=p[Mathf.Max(0,j-1)];var b=p[j];var c=p[j+1];var d=p[Mathf.Min(p.Length-1,j+2)];int n=Mathf.CeilToInt(Vector3.Distance(b,c)/1.3f);for(int k=0;k<n;k++){float t=k/(float)n;points.Add(.5f*((2*b)+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t));}}points.Add(p[p.Length-1]);}}
 static Vector3 P(float x,float z,float y)=>new Vector3(x,y,z);
 public static List<Route> Routes()=>new List<Route>{
 new Route("Cais — praça",4,P(-38,-53,1.8f),P(-42,-45,2),P(-46,-33,3),P(-33,-23,3.8f),P(-16,-19,4.5f),P(0,-11,6)),
 new Route("Praça — igreja",4,P(0,-11,6),P(6,0,7),P(7,13,9.5f),P(-4,24,13),P(-2,31,15)),
 new Route("Rua leste",3.8f,P(-16,-19,4.5f),P(8,-25,3),P(27,-22,3.8f),P(38,-12,5),P(41,-1,7),P(55,15,9),P(47,25,12),P(29,31,13),P(13,30,14),P(-2,31,15)),
 new Route("Casa isolada",3,P(-16,-19,4.5f),P(-18,-5,7),P(-28,4,9),P(-35,14,10),P(-32,24,13),P(-43,32,16),P(-52,38,18)),
 new Route("Caminho da colina",3.5f,P(7,13,9.5f),P(16,24,13),P(22,40,17),P(32,49,20),P(22,58,22),P(7,61,23))};
 static float Smooth(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
 static float Coast(float x,float z){float theta=Mathf.Atan2(z/70,x/66);return Mathf.Sqrt(x*x/(66*66)+z*z/(70*70))+(Mathf.Sin(theta*5+.8f)*.035f+Mathf.Sin(theta*9)*.018f);}
 static float Base(float x,float z){float r=Coast(x,z);float coast=Smooth(1.05f,.88f,r);float hills=2+Smooth(-42,58,z)*17;hills+=3*Mathf.Exp(-((x+48)*(x+48)+(z-38)*(z-38))/450);float beach=1-Smooth(-40,-27,z);float middle=1-Smooth(30,46,Mathf.Abs(x-5));hills=Mathf.Lerp(hills,.55f+Smooth(-65,-30,z)*1.4f,beach*middle);return Mathf.Lerp(-3,hills,coast);}
 static float Dist(Vector2 p,Vector3 a,Vector3 b,out float t){var av=new Vector2(a.x,a.z);var delta=new Vector2(b.x-a.x,b.z-a.z);t=Mathf.Clamp01(Vector2.Dot(p-av,delta)/Mathf.Max(.001f,delta.sqrMagnitude));return Vector2.Distance(p,av+delta*t);}
 static float RoadDistance(Vector2 p,List<Route> routes,out float y,out float width){float best=999;y=0;width=3;foreach(var r in routes)for(int i=1;i<r.points.Count;i++){float t;float d=Dist(p,r.points[i-1],r.points[i],out t);if(d<best){best=d;y=Mathf.Lerp(r.points[i-1].y,r.points[i].y,t);width=r.width;}}return best;}
 static Vector2 Size(string m)=>m=="Church"?new Vector2(7,10):m=="Hall"?new Vector2(9,6):m=="Warehouse"?new Vector2(7,6):m=="OldHouse"?new Vector2(4.2f,5):new Vector2(6,7);
 static float Height(float x,float z,List<Route> routes){float h=Base(x,z);float py,pw;float dist=RoadDistance(new Vector2(x,z),routes,out py,out pw);h=Mathf.Lerp(h,py,1-Smooth(pw/2,pw/2+9,dist));float plaza=Mathf.Sqrt(x*x/225+(z+9)*(z+9)/81);h=Mathf.Lerp(h,6,1-Smooth(.85f,1.25f,plaza));foreach(var p in Plots){var local=Quaternion.Euler(0,-p.yaw,0)*(new Vector3(x,0,z)-new Vector3(p.position.x,0,p.position.z));var sz=Size(p.model);float edge=Mathf.Max(Mathf.Abs(local.x)-sz.x/2,Mathf.Abs(local.z)-sz.y/2);h=Mathf.Lerp(h,p.position.y,1-Smooth(.7f,7,edge));}return h;}
 static Material Mat(string name){return AssetDatabase.LoadAssetAtPath<Material>(Folder+"/"+name+".mat");}
 static Material ColorMat(string name,Color color){var m=Mat(name);if(!m){m=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(m,Folder+"/"+name+".mat");}m.color=color;m.SetFloat("_Glossiness",0);EditorUtility.SetDirty(m);return m;}
 static void Prepare(){Directory.CreateDirectory(Folder);AssetDatabase.Refresh();foreach(var n in new[]{"Plaster","Roof","Wood","Dark","Trim","Awning"}){string path=Art+"/"+n+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.filterMode=FilterMode.Point;ti.mipmapEnabled=false;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.SaveAndReimport();var m=ColorMat(n,Color.white);m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 foreach(string n in Plots.Select(p=>p.model).Distinct()){var src=AssetDatabase.LoadAssetAtPath<GameObject>(Art+"/"+n+".fbx");if(!src)throw new Exception("Modelo ausente: "+n);var root=new GameObject(n);var visual=(GameObject)PrefabUtility.InstantiatePrefab(src,root.transform);foreach(var r in visual.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>Mat(m.name.Replace("I023_", ""))).ToArray();var bounds=ExternalModelNormalizer.BoundsOf(root);visual.transform.localPosition-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);visual.transform.localRotation=Quaternion.Euler(0,180,0);var size=Size(n);var collider=root.AddComponent<BoxCollider>();collider.center=new Vector3(0,(n=="TallHouse"||n=="Shop"?6:3.5f)/2,0);collider.size=new Vector3(size.x,n=="TallHouse"||n=="Shop"?6:3.5f,size.y);root.layer=8;PrefabUtility.SaveAsPrefabAsset(root,Folder+"/"+n+".prefab");UnityEngine.Object.DestroyImmediate(root);}}
 static GameObject Box(Transform parent,string name,Vector3 p,Vector3 sz,Material mat){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(parent,false);go.transform.position=p;go.transform.localScale=sz;go.GetComponent<Renderer>().sharedMaterial=mat;go.layer=8;return go;}
 static GameObject Group(Transform p,string n){var g=new GameObject(n);g.transform.SetParent(p);return g;}
 static void PathMesh(Route r,Transform parent,Terrain terrain){var vertices=new List<Vector3>();var uv=new List<Vector2>();var colors=new List<Color>();var tris=new List<int>();float length=0;for(int i=0;i<r.points.Count;i++){if(i>0)length+=Vector3.Distance(r.points[i-1],r.points[i]);var f=r.points[Mathf.Min(i+1,r.points.Count-1)]-r.points[Mathf.Max(i-1,0)];var right=new Vector3(f.z,0,-f.x).normalized;for(int k=0;k<4;k++){float offset=new[]{-r.width/2-.45f,-r.width/2+.25f,r.width/2-.25f,r.width/2+.45f}[k];var v=r.points[i]+right*offset;v.y=terrain.SampleHeight(v)+terrain.transform.position.y+.045f;vertices.Add(v);uv.Add(new Vector2(offset/2,length/2));colors.Add(new Color(1,1,1,k==0||k==3?0:1));}if(i>0)for(int k=0;k<3;k++){int a=(i-1)*4+k,b=i*4+k;tris.AddRange(new[]{a,b,a+1,a+1,b,b+1});}}
 var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetColors(colors);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();var saved=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/"+r.id+".asset");if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);mesh=saved;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,Folder+"/"+r.id+".asset");var go=Group(parent,r.id);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=Mat("RoadEdge");}
 [MenuItem("Tools/Freyja/Ilha da referência")]
 public static void Build(){var scene=SceneManager.GetActiveScene();if(scene.name!="Ilha_Principal"||EditorApplication.isPlaying)throw new Exception("Abra a cena principal fora de Play.");var existing=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="Island023");if(existing){Selection.activeGameObject=existing;return;}Prepare();var root=new GameObject("Island023");Undo.RegisterCreatedObjectUndo(root,"Criar ilha referência");var routes=Routes();var td=new TerrainData{heightmapResolution=513,alphamapResolution=512,baseMapResolution=512,size=new Vector3(160,40,160)};float[,] h=new float[513,513];for(int z=0;z<513;z++)for(int x=0;x<513;x++)h[z,x]=(Height(x/512f*160-80,z/512f*160-80,routes)+5)/40;td.SetHeights(0,0,h);td.terrainLayers=new[]{"Grass","Dirt","PathSand","BeachSand"}.Select(n=>AssetDatabase.LoadAssetAtPath<TerrainLayer>(KitPS1.Folder+"/"+n+".terrainlayer")).ToArray();var paint=new float[512,512,4];for(int z=0;z<512;z++)for(int x=0;x<512;x++){float px=x/511f*160-80,pz=z/511f*160-80;float sand=(1-Smooth(-39,-27,pz))*(1-Smooth(30,46,Mathf.Abs(px-5)));float noise=Mathf.PerlinNoise(px*.8f,pz*.8f)*.18f; sand=Mathf.Clamp01(sand+noise-.09f);paint[z,x,0]=1-sand;paint[z,x,3]=sand;}td.SetAlphamaps(0,0,paint);AssetDatabase.CreateAsset(td,Folder+"/Terrain.asset");var tg=Terrain.CreateTerrainGameObject(td);tg.name="Terreno — relevo e praia";tg.transform.SetParent(root.transform);tg.transform.position=new Vector3(-80,-5,-80);tg.layer=8;var terrain=tg.GetComponent<Terrain>();terrain.heightmapPixelError=2;
 var road=ColorMat("RoadEdge",Color.white);road.shader=Shader.Find("Freyja/Island Pixel Edge");road.mainTexture=KitPS1.Material("PathSand").mainTexture;var streets=Group(root.transform,"Ruas e caminhos");foreach(var r in routes)PathMesh(r,streets.transform,terrain);
 var plaza=GameObject.CreatePrimitive(PrimitiveType.Cylinder);plaza.name="Praça central";plaza.transform.SetParent(streets.transform);plaza.transform.position=new Vector3(0,5.99f,-9);plaza.transform.localScale=new Vector3(27,.045f,16);plaza.GetComponent<Renderer>().sharedMaterial=KitPS1.Material("Stone");plaza.layer=8;
 var buildings=Group(root.transform,"Construções — 12 casas e 5 serviços");foreach(var p in Plots){var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/"+p.model+".prefab"),buildings.transform);go.name=p.id;go.transform.SetPositionAndRotation(p.position,Quaternion.Euler(0,p.yaw,0));var size=Size(p.model);var foundation=Box(go.transform,"Base de pedra",p.position-new Vector3(0,.2f,0),new Vector3(size.x+.25f,.45f,size.y+.25f),KitPS1.Material("Stone"));foundation.transform.rotation=go.transform.rotation;}
 var dock=Group(root.transform,"Cais e píer");Box(dock.transform,"Cais de pedra",new Vector3(-38,.8f,-54),new Vector3(12,2,10),KitPS1.Material("Stone"));Box(dock.transform,"Píer de madeira",new Vector3(-40,1.65f,-65),new Vector3(3,.3f,14),KitPS1.Material("Bark"));for(int i=0;i<5;i++)for(int side=-1;side<=1;side+=2)Box(dock.transform,"Estaca",new Vector3(-40+side*1.6f,.4f,-59-i*3),new Vector3(.35f,3.7f,.35f),KitPS1.Material("Bark"));
 var props=Group(root.transform,"Pedras e árvores editáveis");var rng=new System.Random(23);for(int i=0;i<145;i++){float angle=i/145f*Mathf.PI*2;float x=Mathf.Cos(angle)*63,z=Mathf.Sin(angle)*66;if(z< -35&&x> -32&&x<48)continue;float y=terrain.SampleHeight(new Vector3(x,0,z))-5;PlaceProp("Rock_"+(1+i%3),new Vector3(x,y-.8f,z),props.transform,new Vector3(3.4f,3.8f,3.6f),i*37);}
 for(int i=0;i<95;i++){float x=(float)rng.NextDouble()*120-60,z=(float)rng.NextDouble()*110-25;float ry,rw;float dist=RoadDistance(new Vector2(x,z),routes,out ry,out rw);if(Coast(x,z)>.87f||dist<rw/2+2||Plots.Any(p=>Vector2.Distance(new Vector2(x,z),new Vector2(p.position.x,p.position.z))<7)||x*x/400+(z+9)*(z+9)/225<1)continue;float y=terrain.SampleHeight(new Vector3(x,0,z))-5;string id=i%3==0?"Nature_Pine":"Nature_Common";float scale=.65f+(float)rng.NextDouble()*.45f;PlaceProp(id,new Vector3(x,y,z),props.transform,Vector3.one*scale,i*47);}
 for(int i=0;i<22;i++){float x=-17+i*2.5f,z=54+Mathf.Sin(i)*4;if(x>6&&x<32)continue;PlaceProp("Rock_"+(1+i%3),new Vector3(x,terrain.SampleHeight(new Vector3(x,0,z))-5,z),props.transform,new Vector3(3,4,3),i*29);}
 var sea=GameObject.CreatePrimitive(PrimitiveType.Plane);sea.name="Mar";sea.transform.SetParent(root.transform);sea.transform.localScale=Vector3.one*60;sea.transform.position=new Vector3(0,0,0);UnityEngine.Object.DestroyImmediate(sea.GetComponent<Collider>());sea.GetComponent<Renderer>().sharedMaterial=ColorMat("Sea",new Color(.13f,.46f,.53f));
 foreach(var go in scene.GetRootGameObjects())if(go!=root&&(go.name.StartsWith("World_")||go.GetComponent<WorldInstanceId>()||new[]{"Cenario","Cenario_Colisao","Galpão do cais e píer","Ilha Tripo 018 - Teste","Blocos 019 - Implantacao","Terreno modular 020 - Teste"}.Contains(go.name)))go.SetActive(false);
 var spawn=Group(root.transform,"Spawn023");spawn.transform.position=new Vector3(-40,1.95f,-69);var session=UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(c=>c.GetType().Name=="CaisSessionController");var so=new SerializedObject(session);so.FindProperty("spawnPoint").objectReferenceValue=spawn.transform;so.FindProperty("recoveryBounds").boundsValue=new Bounds(new Vector3(0,10,0),new Vector3(180,70,180));so.FindProperty("fallHeight").floatValue=-8;so.FindProperty("controlsTitle").stringValue="FREYJA — ILHA";so.ApplyModifiedPropertiesWithoutUndo();var player=GameObject.Find("PlayerPrototype");var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=spawn.transform.position;cc.enabled=true;var cam=GameObject.Find("Cais Gameplay Camera");cam.transform.SetPositionAndRotation(spawn.transform.position+new Vector3(0,4,-9),Quaternion.Euler(18,0,0));AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);Selection.activeGameObject=root;if(SceneView.lastActiveSceneView)SceneView.lastActiveSceneView.LookAt(new Vector3(0,7,0),Quaternion.Euler(48,0,0),100);}
 static void PlaceProp(string id,Vector3 p,Transform parent,Vector3 scale,float yaw){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(KitPS1.Folder+"/"+id+".prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);go.transform.SetPositionAndRotation(p,Quaternion.Euler(0,yaw,0));go.transform.localScale=scale;}
